  protected void onResume(){super.onResume();if(updater!=null)updater.onResume();foreground=true;WatchSync.get(this).refresh();artworks.add(this);if(session!=null){session.add(this);session.onVisible(this);tg.listener=this;if("home".equals(screen))refreshHomeColors();changed();startHomeTick();}}
