  public void changed(){
    if(!screen.equals("home")||session==null)return;
    updateShelf();FeaturedCarousel.attach(this);Movie m=displayedMovie();artworks.active(foreground&&tg.ready);if(foreground&&tg.ready)artworks.prefetch(libraryMovies(),m);String identity=m==null?"":m.cacheIdentity();if(!identity.equals(previewIdentity)){boolean animate=!previewIdentity.isEmpty()&&heroPanel!=null&&heroPanel.isAttachedToWindow()&&TvMotion.enabled(heroPanel);previewIdentity=identity;if(animate){heroPanel.animate().cancel();heroPanel.setAlpha(.8f);heroPanel.animate().alpha(1).setDuration(160).start();}}
    if(title!=null)title.setText(m==null?(libraryFilter.equals("All")&&libraryQuery.isEmpty()?"Your cinema awaits":libraryQuery.isEmpty()?libraryFilter:"No matches"):MediaTitle.parse(m.uiTitle(this)).name);
    if(playFromStartButton!=null)playFromStartButton.setEnabled(m!=null);
    if(continueButton!=null)continueButton.setEnabled(m!=null);
    if(subtitles!=null){
      if(m==null)subtitles.setText(movieCards.isEmpty()&&(!libraryFilter.equals("All")||!libraryQuery.isEmpty())?"Explore All to find your next watch.":"Browse all your Telegram chats to start watching.");
      else {MediaTitle parsed=MediaTitle.parse(m.title);StringBuilder detail=new StringBuilder(parsed.episodic()?String.format(Locale.US,"SERIES  •  S%02d E%02d",parsed.season,parsed.episode):parsed.year>0?"MOVIE  •  "+parsed.year:"MOVIE");detail.append("   •   ").append(size(m.size));if(session.cacheMatches(m)&&!session.subtitlePath.isEmpty())detail.append("\nSubtitle ready   •   ").append(session.subtitleName);subtitles.setText(detail.toString());}
    }
    if(status!=null)status.setText(accountLibrary!=null&&accountLibrary.loading?"Loading your Telegram videos…":accountLibrary!=null&&!accountLibrary.error.isEmpty()?"Could not load videos. Refresh to retry.":session.note==null?"":session.note);
    if(poster!=null)poster.show(m,uiColor);
    if(heroContinueButton!=null){
      boolean matching=session.cacheMatches(m);long duration=m==null?0:(matching&&session.index!=null&&session.index.durationUs>0?session.index.durationUs/1000:m.duration*1000L);
      if(m!=null&&duration<=0)duration=getSharedPreferences("player",0).getLong("duration:"+m.cacheIdentity(),0);
      long pos=m==null?0:m.savedPosition(this);heroContinueButton.setEnabled(m!=null);styleHomeButton(heroContinueButton,false);heroContinueButton.setText(pos>0?"▶  CONTINUE":"▶  PLAY");heroContinueButton.setContentDescription(pos>0?"Continue movie":"Play movie");if(heroContinueButton.hasFocus()&&focusHint!=null)focusHint.setText(heroContinueButton.getContentDescription());resumeSummary.setText(CinemaInfo.resume(pos,duration));resumeProgress.setProgress(CinemaInfo.progress(pos,duration));
      ReadAheadStore store=matching?session.store:null;long cached=store==null?0:store.cachedBytes();boolean failed=(store!=null&&store.failed())||((m==null||session.movie==null||m.cacheIdentity().equals(session.movie.cacheIdentity()))&&CinemaInfo.error(session.note));boolean complete=m!=null&&store!=null&&cached>=m.size&&store.fullyCached();
      movieState.setVisibility(m==null||getResources().getDisplayMetrics().heightPixels/getResources().getDisplayMetrics().density<500?View.GONE:View.VISIBLE);movieState.setText(m==null?"":MediaTitle.parse(m.title).episodic()?"SERIES  /  "+libraryFilter.toUpperCase(Locale.ROOT):"FEATURE FILM  /  "+libraryFilter.toUpperCase(Locale.ROOT));if(m!=null&&MediaTitle.parse(m.title).episodic()){SortedMap<Integer,List<Movie>> seasons=TvLibrary.seasons(seriesMovies(),m);int count=0;for(List<Movie> episodes:seasons.values())count+=episodes.size();subtitles.setText("SERIES  ·  "+seasons.size()+" seasons  ·  "+count+" episodes");heroContinueButton.setText("BROWSE SEASONS");heroContinueButton.setContentDescription("Browse seasons of "+MediaTitle.parse(m.uiTitle(this)).name);}
      if(heroContinueButton.getParent() instanceof View)((View)heroContinueButton.getParent()).setVisibility(m==null?View.GONE:View.VISIBLE);if(moreButton!=null)moreButton.setEnabled(m!=null);boolean episodeGroup=m!=null&&MediaTitle.parse(m.title).episodic();resumeSummary.setVisibility(pos>0&&!episodeGroup?View.VISIBLE:View.GONE);resumeProgress.setVisibility(pos>0&&!episodeGroup?View.VISIBLE:View.GONE);
      status.setVisibility(m==null||failed?View.VISIBLE:View.GONE);
      stateAction.setVisibility(m==null||failed?View.VISIBLE:View.GONE);stateAction.setText(movieCards.isEmpty()&&(!libraryFilter.equals("All")||!libraryQuery.isEmpty())?"Show all":session.channelId==0?"Choose channel":failed?"Retry":"Refresh");ArtworkStore.Entry art=artworks.cached(m);if(artCredit!=null)artCredit.setText(art==null?"": "Artwork: "+art.source+" · "+art.kind);
    }
  }

  void styleFilter(Button chip,String filter){boolean selected=libraryFilter.equals(filter)&&libraryQuery.isEmpty();chip.setSelected(selected);chip.setTextColor(chip.hasFocus()?TmStyle.ON_ACCENT:selected?TmStyle.ACCENT:TmStyle.MUTED);chip.setBackground(TmStyle.pill(this,chip.hasFocus(),selected));}
  void selectHomeFilter(String filter){if(!libraryQuery.isEmpty()&&tg.ready){libraryQuery="";accountLibrary.browse(browseChat,"");}libraryFilter=filter;libraryQuery="";previewMovie=null;shelfKey=null;changed();}
  Movie displayedMovie(){if(previewMovie!=null)return previewMovie;if(!libraryFilter.equals("All")||!libraryQuery.isEmpty())return movieCards.isEmpty()?null:movieCards.get(0).movie;return movieCards.isEmpty()?null:movieCards.get(0).movie;}
  void launchPreview(boolean fromStart){Movie m=displayedMovie();if(m==null)return;if(MediaTitle.parse(m.title).episodic()){openSeries(m);return;}playEpisode(m,fromStart);}
  void playEpisode(Movie m,boolean fromStart){WatchSync.get(this).beforePlay(()->playEpisodeReady(m,fromStart));}
  void playEpisodeReady(Movie m,boolean fromStart){tvLibrary.remember(m);if(session.movie==null||!session.movie.cacheIdentity().equals(m.cacheIdentity())){PlayerActivity.discardWarmPlayer();session.selectMovie(m);}if(fromStart)resetSavedPosition(m);BetaLog.event("play_pressed","mode="+(fromStart?"start":"continue")+" resumeMs="+(fromStart?0:m.savedPosition(this)));List<Movie> queue=MediaTitle.parse(m.title).episodic()?TvLibrary.episodes(seriesMovies(),m):Collections.singletonList(m);int selected=0;for(int i=0;i<queue.size();i++)if(queue.get(i).cacheIdentity().equals(m.cacheIdentity()))selected=i;if(queue.isEmpty())queue=Collections.singletonList(m);play(queue,selected,fromStart);}
  void updateShelf(){
    if(movieRail==null)return;List<Movie> recent=TvLibrary.homeEntries(tvLibrary.list(this,libraryMovies(),libraryFilter,libraryQuery,librarySort));
    if(previewMovie!=null){Movie fresh=null;for(Movie m:recent)if(m.cacheIdentity().equals(previewMovie.cacheIdentity()))fresh=m;previewMovie=fresh;}
    StringBuilder keys=new StringBuilder();for(Movie m:recent)keys.append(m.cacheIdentity()).append('|').append(m.fileId).append('|').append(m.title).append('|').append(m.artwork.hashCode()).append('|').append(m.artworkPath).append(';');String next=keys.toString();
    if(!next.equals(shelfKey)){
      String focused="";for(MovieCardView card:movieCards)if(card.hasFocus())focused=card.movie.cacheIdentity();movieRail.removeAllViews();movieCards.clear();shelfKey=next;
      boolean compact=getResources().getDisplayMetrics().heightPixels/getResources().getDisplayMetrics().density<500;
      for(Movie m:recent){MovieCardView card=new MovieCardView(this,m,compact);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(Ui.dp(this,phoneLayout()?140:compact?88:124),-2);p.rightMargin=Ui.dp(this,10);movieRail.addView(card,p);movieCards.add(card);
        card.setOnFocusChangeListener((v,f)->{card.highlight(f);if(f){previewMovie=card.movie;changed();focusHint.setText(card.getContentDescription());}});
        card.setOnClickListener(v->{previewMovie=card.movie;launchPreview(false);});card.setOnLongClickListener(v->{movieOptions(card.movie);return true;});
      }
      for(int i=0;i<movieCards.size();i++){MovieCardView card=movieCards.get(i);card.setNextFocusLeftId(movieCards.get(Math.max(0,i-1)).getId());card.setNextFocusRightId(movieCards.get(Math.min(movieCards.size()-1,i+1)).getId());card.setNextFocusUpId(heroContinueButton.getId());card.setNextFocusDownId(libraryLoad.getVisibility()==View.VISIBLE?libraryLoad.getId():card.getId());if(card.movie.cacheIdentity().equals(focused))card.requestFocus();}
    }
    for(MovieCardView card:movieCards){card.bind(card.movie);if(MediaTitle.parse(card.movie.title).episodic()){card.episode.setVisibility(View.GONE);card.progress.setVisibility(View.INVISIBLE);card.setContentDescription(MediaTitle.parse(card.movie.title).name+" • Open seasons");}}
    boolean empty=movieCards.isEmpty();emptyLibrary.setVisibility(empty?View.VISIBLE:View.GONE);emptyLibrary.setText(!libraryQuery.isEmpty()?"No matches. Try a shorter title or choose All.":libraryFilter.equals("All")?"Your cinema starts here. Open Chats, or Refresh after signing in.":libraryFilter.equals("Continue")?"Nothing to resume yet. Start a video from All.":"No videos in "+libraryFilter+" yet. Hold OK on a video in All to add it.");
    for(int i=0;i<filterButtons.size();i++){Button chip=filterButtons.get(i);styleFilter(chip,HOME_FILTERS[i]);chip.setNextFocusUpId(heroContinueButton.isEnabled()?heroContinueButton.getId():homeActions[2].getId());chip.setNextFocusDownId(!empty?movieCards.get(0).getId():chip.getId());chip.setNextFocusLeftId(filterButtons.get(Math.max(0,i-1)).getId());chip.setNextFocusRightId(filterButtons.get(Math.min(filterButtons.size()-1,i+1)).getId());}
    if(moreButton!=null)moreButton.setNextFocusDownId(filterButtons.get(0).getId());shelfTitle.setText((!libraryQuery.isEmpty()?"Search: "+libraryQuery:browseChat!=0?accountLibrary.chatTitle(browseChat):libraryFilter.equals("All")?"Recently added · All chats":libraryFilter)+"   ·   "+recent.size()+" titles");movieRail.setVisibility(empty?View.GONE:View.VISIBLE);
    if(libraryLoad!=null){libraryLoad.setId(libraryLoad.getId()==View.NO_ID?View.generateViewId():libraryLoad.getId());boolean more=accountLibrary!=null&&accountLibrary.hasMore()&&tg.ready;libraryLoad.setVisibility(more?View.VISIBLE:View.GONE);libraryLoad.setEnabled(!accountLibrary.loading);libraryLoad.setText(accountLibrary.loading?"Loading…":accountLibrary.error.isEmpty()?"Load more videos":"Retry loading videos");libraryLoad.setNextFocusUpId(!empty?movieCards.get(0).getId():filterButtons.get(0).getId());}
    updateExtraShelves();wireShelfFocus();
    heroContinueButton.setNextFocusDownId(filterButtons.get(Math.max(0,Arrays.asList(HOME_FILTERS).indexOf(libraryFilter))).getId());stateAction.setNextFocusDownId(!empty?movieCards.get(0).getId():heroContinueButton.getId());
  }

  void artworkSource(){Movie m=displayedMovie();ArtworkStore.Entry entry=artworks.cached(m);if(entry==null){Ui.message(this,"Artwork","Online artwork uses promotional movie and series covers from Wikipedia and TVmaze. Episodes share the series cover and show their season/episode label. Missing covers use a title placeholder. Only the cleaned file title is searched.");return;}Ui.dialog(this).setTitle("Artwork · "+entry.source).setMessage(entry.kind+"\n"+entry.page+(entry.source.equals("TVmaze")?"\nTVmaze data · CC BY-SA":"\nImage credits and licence on the source page")).setPositiveButton("Open source",(d,w)->{try{startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(entry.page)));}catch(ActivityNotFoundException e){Toast.makeText(this,"Browser unavailable",Toast.LENGTH_SHORT).show();}}).setNegativeButton("Close",null).show();}
  void settingsPopup(){
    if(tvLibrary!=null){tvSettings();return;}
    Ui.menu(this,"Settings",HOME_SETTINGS_ACTIONS,choice->{
      switch(choice){
        case 5:artworkSource();break;
        case 4:if(updater!=null)updater.checkNow();break;
        case 0:clearVideoCache();break;
        case 1:BetaLog.start(this);Toast.makeText(this,"Log collection started",Toast.LENGTH_SHORT).show();break;
        case 2:BetaLog.stop(this,true);break;
        case 3:LibraryContent.settings(this);break;
      }
    });
  }
  void collections(){Ui.menu(this,"Your cinema",new String[]{"All","Movies","Series","Continue","Watch later","Watched","Sort","Clear search","Remove / clear history"},n->{if(n<6)libraryFilter=new String[]{"All","Movies","Series","Continue","Watch later","Watched"}[n];else if(n==6){Ui.menu(this,"Sort library",new String[]{"Newest","Title A–Z","Smallest first","Largest first"},x->{librarySort=x;shelfKey=null;changed();});return;}else if(n==8){HistoryActions.show(this);return;}else libraryQuery="";previewMovie=null;shelfKey=null;changed();});}
  void searchLibrary(){EditText input=Ui.input(this,"Search title, year, S01E02…",false);input.setText(libraryQuery);Ui.dialog(this).setTitle("Search your library").setView(input).setPositiveButton("Search",(d,w)->{beginSearch(input.getText().toString());}).setNegativeButton("Cancel",null).show();}
  protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==601&&result==RESULT_OK&&data!=null){ArrayList<String> words=data.getStringArrayListExtra(android.speech.RecognizerIntent.EXTRA_RESULTS);if(words!=null&&!words.isEmpty()){beginSearch(words.get(0));}}else if(request==602||request==603)TvBackup.result(this,request,result,data);}
  void movieOptions(Movie movie){tvLibrary.remember(movie);Ui.menu(this,MediaTitle.parse(movie.uiTitle(this)).display(),new String[]{"Play / continue","Play from start","Details","Watch later · "+tvLibrary.marked(movie,"later"),"Watched · "+tvLibrary.marked(movie,"watched"),"Versions","Correct title / artwork","Remove from history"},n->{if(n<2){previewMovie=movie;playEpisode(movie,n==1);}else if(n==2)MovieDetails.show(this,movie);else if(n==3||n==4){tvLibrary.toggle(movie,n==3?"later":"watched");shelfKey=null;changed();}else if(n==5)chooseVersions(movie);else if(n==6)MovieDetails.correct(this,movie);else HistoryActions.remove(this,Collections.singletonList(movie));});}
  void chooseVersions(Movie movie){List<Movie> copies=VideoCopies.available(libraryMovies(),movie);if(copies.isEmpty())copies=Collections.singletonList(movie);final List<Movie> versions=copies;String[] labels=new String[versions.size()];for(int i=0;i<labels.length;i++)labels[i]=SeriesCatalog.quality(versions.get(i))+" · "+size(versions.get(i).size)+" · "+versions.get(i).title;Ui.menu(this,"Versions",labels,n->playEpisode(versions.get(n),false));}
  void tvSettings(){Ui.menu(this,"TG stream · "+BuildConfig.VERSION_NAME,new String[]{"Browse chats","Collections / sort","Movie / episode filters","Appearance / interface size","Autoplay next episode · "+getSharedPreferences("player",0).getBoolean("tvAutoplay",true),"Backup settings & history","Restore backup","Storage review","Start diagnostic log","Stop and send log","Check for update","Artwork credits","Watch progress sync","Signed-in sessions","Notifications / TV launcher"},n->{switch(n){case 0:if(tg.ready)channels();else authChanged(tg.state);break;case 1:collections();break;case 2:LibraryContent.settings(this);break;case 3:Appearance.show(this);break;case 4:SharedPreferences q=getSharedPreferences("player",0);q.edit().putBoolean("tvAutoplay",!q.getBoolean("tvAutoplay",true)).apply();break;case 5:TvBackup.export(this);break;case 6:TvBackup.restore(this);break;case 7:StorageReview.show(this);break;case 8:BetaLog.start(this);Toast.makeText(this,"Diagnostic log started",Toast.LENGTH_SHORT).show();break;case 9:BetaLog.stop(this,true);break;case 10:updater.checkNow();break;case 11:artworkSource();break;case 12:WatchSync.get(this).refresh();Ui.message(this,"Watch progress sync",WatchSync.get(this).status+"\nYour Telegram Saved Messages keep progress for your other devices.");break;case 13:TelegramSessions.show(this);break;case 14:ContentAlerts.settings(this);}});}
  @Override public boolean dispatchKeyEvent(KeyEvent event){if(event.getAction()==KeyEvent.ACTION_DOWN&&event.getKeyCode()==KeyEvent.KEYCODE_MENU&&"home".equals(screen)){Movie selected=displayedMovie();if(selected!=null)movieOptions(selected);else tvSettings();return true;}return super.dispatchKeyEvent(event);}
  void resetSavedPosition(Movie m){getSharedPreferences("player",0).edit().remove("pos:"+m.cacheIdentity()).remove("pos:"+m.uri).remove("pos:"+m.legacyUri()).apply();if(session!=null&&session.movie!=null&&session.movie.cacheIdentity().equals(m.cacheIdentity()))session.updatePosition(0);}
  void channels(){if(!tg.ready){authChanged(tg.state);return;}screen="chats";page("Your Telegram chats");action("All movies · every chat",()->{openGrid(0);});action("Back to Home",this::home);chatRows=new LinearLayout(this);chatRows.setOrientation(LinearLayout.VERTICAL);column.addView(chatRows);renderChats();if(accountLibrary.chats.isEmpty())accountLibrary.loadChats();}
  void renderChats(){if(!"chats".equals(screen)||chatRows==null)return;chatRows.removeAllViews();status.setText(accountLibrary.chatLoading?"Loading chats…":accountLibrary.error.isEmpty()?"Channels, groups, people, Saved Messages and archived chats":"Could not load chats. Try again.");for(Map.Entry<Long,String> entry:accountLibrary.chats.entrySet()){long id=entry.getKey();Ui.add(chatRows,Ui.button(this,entry.getValue(),()->{openGrid(id);}));}if(!accountLibrary.mainDone||!accountLibrary.archiveDone){Button more=Ui.button(this,accountLibrary.chatLoading?"Loading chats…":"Load more chats (including archive)",()->accountLibrary.loadChats());more.setEnabled(!accountLibrary.chatLoading);Ui.add(chatRows,more);}}
  void startLibrary(){if(accountLibrary!=null&&tg.ready&&!libraryStarted){libraryStarted=true;accountLibrary.browse(0,"");}}
  void refreshLibrary(){if(!tg.ready){authChanged(tg.state);return;}libraryStarted=true;accountLibrary.browse(browseChat,libraryQuery);if(session.channelId!=0)session.refresh();}
  void beginSearch(String text){libraryFilter="All";libraryQuery=text.trim();previewMovie=null;shelfKey=null;if(tg.ready)accountLibrary.browse(browseChat,libraryQuery);if(screen.equals("videos"))renderGrid();else changed();}
  @Override public void libraryChanged(){if(accountLibrary!=null)ContentAlerts.observe(this,accountLibrary.items());if("chats".equals(screen))renderChats();else if("videos".equals(screen))renderGrid();else if("home".equals(screen)){shelfKey=null;changed();}}
  List<Movie> libraryMovies(){List<Movie> loaded=accountLibrary==null?Collections.emptyList():accountLibrary.items();if(!libraryQuery.isEmpty())return loaded;List<Movie> merged=TelegramLibrary.merge(loaded,session.recentMovies);if(session.movie!=null)merged=TelegramLibrary.merge(merged,Collections.singletonList(session.movie));if(browseChat!=0)merged.removeIf(m->m.chatId!=browseChat);for(Movie item:merged)item.groupOverride=getSharedPreferences("metadata-corrections",0).getString("group:"+item.cacheIdentity(),item.groupOverride);return merged;}
  void updateExtraShelves(){if(extraShelves==null)return;boolean home=browseChat==0&&libraryQuery.isEmpty()&&libraryFilter.equals("All");List<Movie> all=libraryMovies();StringBuilder signature=new StringBuilder(Boolean.toString(home));for(Movie m:all)signature.append(m.cacheIdentity()).append(':').append(m.savedPosition(this));String key=signature.toString();if(key.equals(extraShelfKey))return;extraShelfKey=key;extraShelves.removeAllViews();extraRows.clear();if(!home)return;List<Movie> continuing=tvLibrary.list(this,all,"Continue","",0);if(!continuing.isEmpty())addExtraShelf("Continue watching",continuing);}
  void addExtraShelf(String name,List<Movie> movies){List<MovieCardView> cards=new ArrayList<>();extraRows.add(cards);TextView heading=TmHome.label(this,name,17,TmStyle.TEXT);heading.setTypeface(Typeface.DEFAULT_BOLD);extraShelves.addView(heading);HorizontalScrollView scroll=new HorizontalScrollView(this);scroll.setHorizontalScrollBarEnabled(false);LinearLayout row=new LinearLayout(this);scroll.addView(row);int count=0;for(Movie m:TvLibrary.homeEntries(movies)){if(count++==12)break;MovieCardView card=new MovieCardView(this,m,false);if(MediaTitle.parse(m.title).episodic()){card.episode.setVisibility(View.GONE);card.progress.setVisibility(View.INVISIBLE);}LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(Ui.dp(this,phoneLayout()?140:108),-2);lp.rightMargin=Ui.dp(this,10);row.addView(card,lp);cards.add(card);card.setOnFocusChangeListener((v,f)->card.highlight(f));card.setOnClickListener(v->{previewMovie=m;launchPreview(false);});card.setOnLongClickListener(v->{movieOptions(m);return true;});}extraShelves.addView(scroll);}
  void wireShelfFocus(){List<MovieCardView> continuing=extraRows.isEmpty()?Collections.emptyList():extraRows.get(0);int filters=filterButtons.get(0).getId();int first=movieCards.isEmpty()?filters:movieCards.get(0).getId();boolean more=libraryLoad!=null&&libraryLoad.getVisibility()==View.VISIBLE;for(MovieCardView card:movieCards){card.setNextFocusUpId(filters);card.setNextFocusDownId(more?libraryLoad.getId():card.getId());}for(int i=0;i<continuing.size();i++){MovieCardView card=continuing.get(i);card.setNextFocusUpId(heroContinueButton.getId());card.setNextFocusDownId(filters);card.setNextFocusLeftId(continuing.get(Math.max(0,i-1)).getId());card.setNextFocusRightId(continuing.get(Math.min(i+1,continuing.size()-1)).getId());}if(more){libraryLoad.setNextFocusUpId(first);libraryLoad.setNextFocusDownId(libraryLoad.getId());}}
  void openGrid(long chat){browseChat=chat;libraryFilter="All";libraryQuery="";previewMovie=null;screen="videos";accountLibrary.browse(chat,"");showGrid();}
  void showGrid(){screen="videos";page(browseChat==0?"All movies · All chats":accountLibrary.chatTitle(browseChat));action("Back to Home",this::returnHome);action("Search this library",this::searchLibrary);gridBody=new LinearLayout(this);gridBody.setOrientation(LinearLayout.VERTICAL);column.addView(gridBody);renderGrid();}
  void renderGrid(){if(gridBody==null||!screen.equals("videos"))return;String focused="";View focus=getCurrentFocus();if(focus instanceof MovieCardView)focused=((MovieCardView)focus).movie.cacheIdentity();gridBody.removeAllViews();status.setText(accountLibrary.loading?"Loading videos…":!accountLibrary.error.isEmpty()?"Could not load videos. Retry below.":"Videos and video files · "+accountLibrary.items().size()+" loaded");int columns=phoneLayout()?2:5;android.widget.GridLayout grid=new android.widget.GridLayout(this);grid.setColumnCount(columns);int available=getResources().getDisplayMetrics().widthPixels-Ui.dp(this,72);int width=available/columns;List<Movie> movies=TvLibrary.homeEntries(tvLibrary.list(this,libraryMovies(),"All",libraryQuery,librarySort));for(Movie m:movies){MovieCardView card=new MovieCardView(this,m,false);GridLayout.LayoutParams lp=new GridLayout.LayoutParams();lp.width=width;lp.height=-2;lp.bottomMargin=Ui.dp(this,16);grid.addView(card,lp);card.setOnFocusChangeListener((v,f)->card.highlight(f));card.setOnClickListener(v->{previewMovie=m;launchPreview(false);});card.setOnLongClickListener(v->{movieOptions(m);return true;});if(focused.equals(m.cacheIdentity()))card.requestFocus();}gridBody.addView(grid);if(movies.isEmpty()&&!accountLibrary.loading)Ui.add(gridBody,Ui.text(this,"No playable videos found. Try another chat or search.",16,TmStyle.MUTED));if(accountLibrary.hasMore()){Button more=Ui.button(this,accountLibrary.loading?"Loading…":"Load more videos",()->accountLibrary.loadMore());more.setEnabled(!accountLibrary.loading);Ui.add(gridBody,more);}}
  void clearVideoCache(){Ui.dialog(this).setTitle("Clear temporary stream cache?").setMessage("Saved positions, subtitles and Telegram login stay.").setPositiveButton("Clear",(d,w)->{PlayerActivity.discardWarmPlayer();session.tasks.execute(()->{synchronized(session){Movie m=session.movie;session.closeStore();if(m!=null){session.tg.deleteCached(m.fileId);MediaCache.delete(MediaCache.directory(this,m.cacheIdentity()));}}session.notifyChanged();});}).setNegativeButton("Cancel",null).show();}
  static String size(long n){if(n<=0)return "Stream";if(n>=1024L*1024*1024)return String.format(Locale.US,"%.2f GB",n/(1024.0*1024*1024));return String.format(Locale.US,"%.0f MB",n/1048576.0);}
  static String duration(long s){return s>=3600?String.format(Locale.US,"%d:%02d:%02d",s/3600,(s/60)%60,s%60):String.format(Locale.US,"%d:%02d",s/60,s%60);}
  void play(List<Movie> list,int selected,boolean fromStart){JSONArray array=new JSONArray();for(Movie m:list)array.put(m.json());startActivity(new Intent(this,PlayerActivity.class).addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT).putExtra("movies",array.toString()).putExtra("index",selected).putExtra("startFromBeginning",fromStart));}
  public void onBackPressed(){if(screen.equals("episodes")||screen.equals("seasons")){if(seriesReturn.equals("videos")){screen="videos";showGrid();}else home();return;}if(screen.equals("splash")){openHome();return;}if(!screen.equals("home"))returnHome();else{PlayerActivity.discardWarmPlayer();session.pause();finishAffinity();}}

